def encode(message):
    """
    Write a function that takes a message, and encodes in such a 
    way that it swaps case of all letters, replaces all vowels in 
    the message with the letter that appears 2 places ahead of that 
    vowel in the english alphabet. 
    Assume only letters. 

    Examples:
    >>> encode('test')
    'TGST'
    >>> encode('This is a message')
    'tHKS KS C MGSSCGG'
    """
    vowels = 'aeiou'
    encoded_message = ''
    for char in message:
        if char.isalpha():
            if char.islower():
                if char in vowels:
                    encoded_message += chr(ord('z') + (ord(char) - ord('a')) + 2)
                else:
                    encoded_message += chr(ord('A') + (ord(char) - ord('a')) + 2)
            else:
                if char in vowels:
                    encoded_message += chr(ord('Z') + (ord(char) - ord('a')) + 2)
                else:
                    encoded_message += chr(ord('a') + (ord(char) - ord('a')) + 2)
        else:
            encoded_message += char
