    split_words("Hello,world!") ➞ ["Hello", "world!"]
    split_words("abcdef") == 3 
    '''
    # Split on whitespace
    if ' ' in txt:
        return txt.split()
    # Split on commas
    elif ',' in txt:
        return txt.split(',')
    # Split on lower-case letters with odd order
    else:
        count = 0
        for char in txt:
            if 'a' <= char <= 'z' and ord(char) % 2 != 0:
                count += 1
        return count
